(function(){'use strict';var S=window.vitalstackShare||{};try{var tz=Intl.DateTimeFormat().resolvedOptions().timeZone||'';if(tz&&document.cookie.indexOf('vs_tz='+encodeURIComponent(tz))===-1){document.cookie='vs_tz='+encodeURIComponent(tz)+'; path=/; max-age=31536000; samesite=lax'+(location.protocol==='https:'?'; secure':'');}}catch(e){}
var panel=document.querySelector('[data-ref]');if(panel){var input=panel.querySelector('[data-ref-link]');var copyBtn=panel.querySelector('[data-ref-copy]');if(copyBtn&&input){copyBtn.addEventListener('click',function(){var done=function(){var t=copyBtn.textContent;copyBtn.textContent=S.copied||'Copied!';setTimeout(function(){copyBtn.textContent=t;},1800);};if(navigator.clipboard&&navigator.clipboard.writeText)navigator.clipboard.writeText(input.value).then(done,function(){input.select();document.execCommand('copy');done();});else{input.select();document.execCommand('copy');done();}});input.addEventListener('focus',function(){input.select();});}
var native=panel.querySelector('[data-ref-native]');if(native&&navigator.share&&input){native.hidden=false;native.addEventListener('click',function(){navigator.share({title:S.site||document.title,text:native.getAttribute('data-text')||'',url:input.value}).catch(function(){});});}
if(location.hash==='#invite')panel.scrollIntoView({block:'start'});panel.id=panel.id||'invite';}
var apply=document.querySelector('[data-ref-apply]');if(apply){var code=apply.getAttribute('data-ref-apply');var box=document.querySelector('[data-coupon]');var go=document.querySelector('[data-coupon-apply]');if(box&&go&&code){var details=box.closest('details');if(details)details.open=true;box.value=code;setTimeout(function(){go.click();},50);}}
if(!S.loggedIn&&S.welcome&&/(?:^|;\s*)vs_ref_hi=1/.test(document.cookie)&&!/[?&]tab=register/.test(location.search)){var bar=document.createElement('div');bar.className='ref-welcome';bar.setAttribute('role','status');var p=document.createElement('p');p.textContent=S.welcome;var a=document.createElement('a');a.className='btn btn-primary btn-sm';a.href=S.joinUrl;a.textContent=S.join;var x=document.createElement('button');x.type='button';x.className='ref-welcome-x';x.setAttribute('aria-label',S.close||'Close');x.textContent='×';x.addEventListener('click',function(){bar.remove();document.cookie='vs_ref_hi=; Max-Age=0; path=/';});bar.appendChild(p);bar.appendChild(a);bar.appendChild(x);document.body.appendChild(bar);}
var article=document.body.classList.contains('single')?document.querySelector('main .prose'):null;if(article){document.addEventListener('copy',function(e){var sel=window.getSelection();if(!sel||sel.isCollapsed||!e.clipboardData)return;var node=sel.anchorNode&&(sel.anchorNode.nodeType===1?sel.anchorNode:sel.anchorNode.parentElement);if(!node||!article.contains(node)||node.closest('pre, code, input, textarea, [contenteditable], .tool, .vs-protected'))return;var text=sel.toString();if(text.length<200)return;var url=location.origin+location.pathname;e.clipboardData.setData('text/plain',text+'\n\n'+(S.source||'Source')+': '+(S.site?S.site+' · ':'')+url);e.preventDefault();});}
var coursesPanel=document.getElementById('courses-panel');if(coursesPanel){coursesPanel.querySelectorAll('.courses-group small').forEach(function(s){var m=/^\s*(\d+)\s+(.+)$/.exec(s.textContent);if(!m||s.querySelector('b'))return;s.setAttribute('title',s.textContent.trim());s.textContent='';var n=document.createElement('b');n.textContent=m[1];var u=document.createElement('i');u.textContent=' '+m[2];s.appendChild(n);s.appendChild(u);});var fitNames=function(){var phone=window.matchMedia('(max-width: 719px)').matches;coursesPanel.querySelectorAll('.courses-group a > span').forEach(function(el){if(!el.title)el.title=el.textContent.trim();el.style.fontSize='';if(el.textContent!==el.title)el.textContent=el.title;if(!phone||!el.offsetParent)return;var size=parseFloat(getComputedStyle(el).fontSize)||15;var shrink=function(min){while(el.scrollWidth>el.clientWidth+1&&size>min){size-=0.5;el.style.fontSize=size+'px';}};shrink(12);if(el.scrollWidth>el.clientWidth+1){el.textContent=el.title.replace(/\s+and\s+/g,' & ').replace(/\s*\([^)]*\)\s*$/,'');shrink(11);if(el.scrollWidth>el.clientWidth+1&&el.title.indexOf(':')>0){el.textContent=el.title.split(':')[0];}}});};document.querySelectorAll('[data-courses-open]').forEach(function(b){b.addEventListener('click',function(){setTimeout(fitNames,60);});});var fitTimer;window.addEventListener('resize',function(){clearTimeout(fitTimer);fitTimer=setTimeout(fitNames,150);});if(!coursesPanel.hidden&&coursesPanel.offsetParent)fitNames();}
var cookieNote=document.getElementById('cookie-note');var liftNotes=function(){var h=cookieNote&&!cookieNote.hidden&&getComputedStyle(cookieNote).display!=='none'?Math.ceil(cookieNote.getBoundingClientRect().height)+12:0;document.documentElement.style.setProperty('--vs-cookie-h',h+'px');};if(cookieNote){liftNotes();new MutationObserver(liftNotes).observe(cookieNote,{attributes:true,attributeFilter:['hidden','class','style']});window.addEventListener('resize',liftNotes);}
var payRoot=document.querySelector('[data-pay]');if(payRoot){var syncOffer=function(){payRoot.querySelectorAll('[data-plan-card]').forEach(function(card){var amt=card.querySelector('.plan-amount');var cur=amt&&/^\s*\$/.test(amt.textContent)?'usd':'inr';card.querySelectorAll('[data-x-inr]').forEach(function(el){var t=el.getAttribute('data-x-'+cur)||'';if(el.textContent!==t)el.textContent=t;if(el.hidden!==!t)el.hidden=!t;});});};syncOffer();payRoot.addEventListener('click',function(e){if(e.target.closest('[data-cur]'))setTimeout(syncOffer,30);});new MutationObserver(syncOffer).observe(payRoot,{subtree:true,characterData:true,childList:true});}
document.querySelectorAll('[data-offer]').forEach(function(box){var rule=box.getAttribute('data-cur-rule')||'auto';var tz='';try{tz=Intl.DateTimeFormat().resolvedOptions().timeZone||'';}catch(e){}
var srv=box.getAttribute('data-cur')||'';var cur=srv==='inr'||srv==='usd'?srv:(rule==='inr'?'inr':(/^Asia\/(Kolkata|Calcutta)$/.test(tz)?'inr':'usd'));box.querySelectorAll('[data-x-inr]').forEach(function(el){var t=el.getAttribute('data-x-'+cur)||'';if(el.textContent!==t)el.textContent=t;el.hidden=!t;});});var topicBar=document.querySelector('.topicbar-row .topicbar-inner');if(topicBar){var alignTopics=function(){var prevBtn=document.querySelector('[data-topic-scroll="-1"]');if(!prevBtn||prevBtn.hidden||topicBar.scrollLeft<=2)return;var edge=topicBar.getBoundingClientRect().left+prevBtn.getBoundingClientRect().width+4;var links=topicBar.querySelectorAll(':scope > a');for(var i=0;i<links.length;i++){var r=links[i].getBoundingClientRect();if(r.right>edge+1){if(r.left<edge-1)topicBar.scrollBy({left:r.left-edge,behavior:'smooth'});break;}}};var topicTimer;topicBar.addEventListener('scroll',function(){clearTimeout(topicTimer);topicTimer=setTimeout(alignTopics,160);},{passive:true});setTimeout(alignTopics,400);}
document.querySelectorAll('.site-footer .footer-col').forEach(function(col){var list=col.querySelector('ul');if(!list||list.children.length<=14)return;var more=list.children.length-12;col.classList.add('is-collapsed');var btn=document.createElement('button');btn.type='button';btn.className='footer-more';btn.setAttribute('aria-expanded','false');var label=function(){btn.textContent=col.classList.contains('is-collapsed')?'+'+more+' more courses ▾':'Show fewer ▴';};label();btn.addEventListener('click',function(){col.classList.toggle('is-collapsed');col.classList.toggle('is-expanded',!col.classList.contains('is-collapsed'));btn.setAttribute('aria-expanded',col.classList.contains('is-collapsed')?'false':'true');label();});list.parentNode.insertBefore(btn,list.nextSibling);});})();